@st.cache_data(ttl=300)
def load_data():
    if not DATA_FILE.exists():
        return []
    with DATA_FILE.open("r", encoding="utf-8") as f:
        data = json.load(f)
    return data if isinstance(data, list) else []


@st.cache_data(ttl=900, show_spinner=False)
def github_last_commit(repo):
    if not repo or "/" not in repo:
        return {}
    headers = {
        "Accept": "application/vnd.github+json",
        "User-Agent": "grupo-dauto-dashboard-portal",
    }
    try:
        token = st.secrets.get("GITHUB_TOKEN", "")
    except Exception:
        token = ""
    if token:
        headers["Authorization"] = f"Bearer {token}"
    try:
        r = requests.get(
            f"https://api.github.com/repos/{repo}/commits",
            params={"per_page": 1},
            headers=headers,
            timeout=8,
        )
        if r.status_code != 200:
            return {}
        commits = r.json()
        if not commits:
            return {}
        item = commits[0]
        commit = item.get("commit", {})
        author = commit.get("author", {}) or {}
        return {
            "date": author.get("date", ""),
            "author": author.get("name", ""),
            "message": (commit.get("message", "") or "").splitlines()[0],
        }
    except requests.RequestException:
        return {}


def format_date(value):
    if not value:
        return ""
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00")).astimezone(ZoneInfo("America/Sao_Paulo"))
        return dt.strftime("%d/%m/%Y às %H:%M")
    except ValueError:
        return value


def whatsapp_link(name, url):
    text = f"Olá! Segue o acesso ao {name}:\n\n{url}"
    return f"https://wa.me/?text={quote(text)}"


def searchable(item):
    return " ".join(str(item.get(k, "")) for k in
                    ("nome", "descricao", "categoria", "tipo")).lower()




@st.dialog("Acesso protegido")
def solicitar_senha_acao(
    nome: str,
    url: str,
    acao: str,
    item_hash: str,
) -> None:
    """Solicita senha antes de executar uma ação em painel protegido."""

    st.markdown(f"**{html.escape(nome)}**")
    st.caption(
        "Este painel possui acesso protegido. "
        "Digite a senha para continuar."
    )

    senha_digitada = st.text_input(
        "Senha",
        type="password",
        key=f"senha_dialog_{item_hash}_{acao}",
        placeholder="Digite a senha de acesso",
    )

    validar = st.button(
        "Validar senha",
        key=f"validar_dialog_{item_hash}_{acao}",
        type="primary",
        use_container_width=True,
    )

    if validar:
        if senha_digitada != PAINEL_PASSWORD:
            st.error("Senha incorreta.")
            return

        st.success("Senha validada.")

        if acao == "acessar":
            st.link_button(
                "Continuar para o painel",
                url,
                type="primary",
                use_container_width=True,
            )

        elif acao == "whatsapp":
            st.link_button(
                "Abrir no WhatsApp",
                whatsapp_link(nome, url),
                type="primary",
                use_container_width=True,
            )

        elif acao == "copiar":
            st.caption("Use o ícone de cópia no bloco abaixo:")
            st.code(url, language=None, wrap_lines=True)


